            sentences=listOf(StorySentence("Selin had prepared carefully for a conventional interview.", "Selin geleneksel bir iş görüşmesine dikkatle hazırlanmıştı."), StorySentence("Instead, the interviewer spent most of the time asking about a volunteer project mentioned at the bottom of her CV.", "Bunun yerine görüşmeci zamanın çoğunu CV’nin altındaki gönüllü projeyi sorarak geçirdi."), StorySentence("At first, Selin worried that the conversation had gone off track.", "Başta Selin konuşmanın konudan saptığından endişelendi."), StorySentence("Then she realised the interviewer was testing how she handled uncertainty and explained decisions.", "Sonra görüşmecinin belirsizlikle nasıl baş ettiğini ve kararları nasıl açıkladığını test ettiğini fark etti."), StorySentence("She stopped giving rehearsed answers and began speaking more naturally.", "Ezber cevaplar vermeyi bırakıp daha doğal konuşmaya başladı."), StorySentence("That change probably did more for her than all the preparation.", "Bu değişiklik muhtemelen tüm hazırlıktan daha çok işine yaradı.")),
            vocabulary=listOf(VocabItem("conventional", "geleneksel", "Selin had prepared carefully for a conventional interview.", "Selin geleneksel bir iş görüşmesine dikkatle hazırlanmıştı."), VocabItem("off track", "konudan sapmış", "At first, Selin worried that the conversation had gone off track.", "Başta Selin konuşmanın konudan saptığından endişelendi."), VocabItem("rehearsed", "ezberlenmiş/prova edilmiş", "She stopped giving rehearsed answers and began speaking more naturally.", "Ezber cevaplar vermeyi bırakıp daha doğal konuşmaya başladı.")),
