            sentences=listOf(StorySentence("During negotiations, Arda used to treat every silence as a problem that needed filling.", "Arda müzakerelerde her sessizliği doldurulması gereken bir sorun olarak görürdü."), StorySentence("He would rush to add explanations, often weakening a point he had already made clearly.", "Açıklama eklemek için acele eder, çoğu zaman zaten net söylediği bir noktayı zayıflatırdı."), StorySentence("A more experienced colleague suggested an experiment: make the point, then wait.", "Daha deneyimli bir meslektaşı bir deney önerdi: fikri söyle, sonra bekle."), StorySentence("The result surprised him.", "Sonuç onu şaşırttı."), StorySentence("Silence gave other people room to think and often encouraged them to reveal more.", "Sessizlik diğer insanlara düşünme alanı verdi ve çoğu zaman daha fazla şey açıklamalarını teşvik etti."), StorySentence("Arda learned that fluent communication was not the same as continuous speech.", "Arda akıcı iletişimin kesintisiz konuşmakla aynı şey olmadığını öğrendi.")),
